#ifdef ENABLE_TARGET_AVX
      orc_avx_init();
#endif
#ifdef ENABLE_TARGET_AVX512
      orc_avx512_init();
#endif
#ifdef ENABLE_TARGET_ALTIVEC
      orc_powerpc_init();
#endif
#ifdef ENABLE_TARGET_ARM
      orc_arm_init();
