#ifdef ENABLE_TARGET_MIPS
      orc_mips_init();
#endif
#ifdef ENABLE_TARGET_RISCV
      orc_riscv_init();
#endif
#ifdef ENABLE_TARGET_LSX
      orc_lsx_init();
#endif
#ifdef ENABLE_TARGET_LASX
      orc_lasx_init();
#endif

      inited = TRUE;
    }
    orc_global_mutex_unlock ();
  }
}

