137: void
138: _orc_compiler_init (void)
139: {
140:   char *envvar;
141: #ifdef HAVE_CODEMEM_VIRTUALALLOC
142:   #ifdef ORC_WINAPI_ONLY_APP
143:     size_t page_size;
144:   #else
145:     size_t page_size ORC_GNUC_UNUSED;
146:   #endif
147: 
148:   SYSTEM_INFO info;
149: #endif
150: 
151:   envvar = _orc_getenv ("ORC_CODE");
152:   if (envvar != NULL) {
153:     _orc_compiler_flag_list = strsplit (envvar, ',');
154:     free (envvar);
155:   }
156: 
157:   _orc_compiler_flag_backup = orc_compiler_flag_check ("backup");
158:   _orc_compiler_flag_emulate = orc_compiler_flag_check ("emulate");
159:   _orc_compiler_flag_debug = orc_compiler_flag_check ("debug");
160:   _orc_compiler_flag_randomize = orc_compiler_flag_check ("randomize");
161: 
162: #ifdef HAVE_CODEMEM_VIRTUALALLOC
163:   GetNativeSystemInfo(&info);
164:   page_size = info.dwPageSize;
165: 
166:   /* Protection attribute change via VirtualProtect will be applied per
167:    * page memory unit. So we should split code memory with page aligned range.
168:    * Otherwise the protection attribute of previously generated executable code
169:    * memory can be affected by later generated one.
170:    */
171:   _orc_codemem_alignment = info.dwPageSize - 1;
172: #else
173:   /* 16 bytes alignment by default */
174:   _orc_codemem_alignment = 15;
175: #endif
176: 
177:   int can_jit = TRUE;
178: 
179:   if (!_orc_compiler_flag_backup && !_orc_compiler_flag_emulate) {
180:     /* If backup code is not enabled and emulation is not enabled, that means
181:      * we will do JIT compilation and call orc_code_region_allocate_codemem().
182:      */
183: #if defined(HAVE_CODEMEM_VIRTUALALLOC) && defined(ORC_WINAPI_ONLY_APP)
184:     /* When targeting Windows Store apps, the codeGeneration capability must
185:      * be enabled in the app manifest, or passing PAGE_EXECUTE to
186:      * VirtualProtectFromApp will return NULL. In this case, we must force
187:      * backup C code, and if that's not available, we must emulate. */
188:     can_jit = FALSE;
189:     void *mem = VirtualAllocFromApp (NULL, page_size, MEM_COMMIT,
190:         PAGE_READWRITE);
191:     if (mem) {
192:       int old_protect;
193:       if (VirtualProtectFromApp (mem, page_size, PAGE_EXECUTE, &old_protect) > 0)
194:         can_jit = TRUE;
195:       VirtualFree (mem, 0, MEM_RELEASE);
196:     } else {
197:       ORC_WARNING ("Unable to allocate executable pages: using backup code or "
198:         "emulation: codeGeneration capability isn't set in the app manifest?");
199:     }
200: #elif defined(HAVE_CODEMEM_MMAP)
201:     /* In this case, we need to check that we can mmap pages as executable.
202:      * This is not the case under the combination of SELinux and sandboxing
203:      * profiles.
204:      */
205:     can_jit = FALSE;
206:     OrcCodeRegion *region = orc_code_region_alloc();
207:     if (region) {
208:       can_jit = TRUE;
209:       // FIXME: the file descriptor should be kept somewhere
210:       // Currently the underlying mmap'd pages are leaked
211:       free(region);
212:     } else {
213:       ORC_WARNING ("Unable to allocate executable pages: using backup code or emulation");
214:     }
215: #endif
216: 
217:     if (!can_jit) {
218:       _orc_compiler_flag_backup = TRUE;
219:       _orc_compiler_flag_emulate = TRUE;
220:     }
221:   }
222: }
