237: static int
238: orc_compiler_allocate_register (OrcCompiler *compiler, int data_reg)
239: {
240:   int i;
241:   int roff;
242:   int reg;
243:   int offset;
244: 
245:   if (data_reg) {
246:     offset = compiler->target->data_register_offset;
247:   } else {
248:     offset = ORC_GP_REG_BASE;
249:   }
250: 
251:   roff = 0;
252:   if (_orc_compiler_flag_randomize) {
253:     /* for testing */
254:     roff = rand()&0x1f;
255:   }
256: 
257:   for (i = 0; i < ORC_N_REGS; i++) {
258:     // For volatile registers, try up to 32 registers from offset
259:     // Amyspark: this ensures that we don't run over vector registers
260:     reg = offset + ((roff + i) & 0x1f);
261:     if (compiler->valid_regs[reg] &&
262:         !compiler->save_regs[reg] &&
263:         compiler->alloc_regs[reg] == 0) {
264:       compiler->alloc_regs[reg]++;
265:       compiler->used_regs[reg] = 1;
266:       return reg;
267:     }
268:   }
269:   // Use ORC_N_REGS to ensure forward proofed iteration
270:   for (i = 0; i < ORC_N_REGS; i++) {
271:     // Try with up to 64 registers starting from offset
272:     // If this lands us within vector range, bail out
273:     reg = offset + ((roff + i) & 0x3f);
274:     if (reg >= compiler->target->data_register_offset && !data_reg)
275:       break;
276:     if (compiler->valid_regs[reg] && compiler->alloc_regs[reg] == 0) {
277:       compiler->alloc_regs[reg]++;
278:       compiler->used_regs[reg] = 1;
279:       return reg;
280:     }
281:   }
282: 
283:   if (data_reg || !compiler->allow_gp_on_stack) {
284:     ORC_COMPILER_ERROR (compiler, "register overflow for %s register",
285:         data_reg ? "vector" : "gp");
286:     compiler->result = ORC_COMPILE_RESULT_UNKNOWN_COMPILE;
287:   }
288: 
289:   return 0;
290: }
