715: static void
716: orc_compiler_check_sizes (OrcCompiler *compiler)
717: {
718:   int i;
719:   int j;
720:   int max_size = 1;
721: 
722:   for(i=0;i<compiler->n_insns;i++) {
723:     OrcInstruction *insn = compiler->insns + i;
724:     OrcStaticOpcode *opcode = insn->opcode;
725:     int multiplier = 1;
726: 
727:     if (insn->flags & ORC_INSTRUCTION_FLAG_X2) {
728:       multiplier = 2;
729:     } else if (insn->flags & ORC_INSTRUCTION_FLAG_X4) {
730:       multiplier = 4;
731:     }
732: 
733:     for(j=0;j<ORC_STATIC_OPCODE_N_DEST;j++){
734:       if (opcode->dest_size[j] == 0) continue;
735:       if (multiplier * opcode->dest_size[j] !=
736:           compiler->vars[insn->dest_args[j]].size) {
737:         ORC_COMPILER_ERROR (compiler, "size mismatch, opcode %s dest[%d] is %d should be %d",
738:             opcode->name, j, compiler->vars[insn->dest_args[j]].size,
739:             multiplier * opcode->dest_size[j]);
740:         compiler->result = ORC_COMPILE_RESULT_UNKNOWN_PARSE;
741:         return;
742:       }
743:       max_size = MAX(max_size, multiplier * opcode->dest_size[j]);
744:     }
745:     for(j=0;j<ORC_STATIC_OPCODE_N_SRC;j++){
746:       if (opcode->src_size[j] == 0) continue;
747:       if (multiplier * opcode->src_size[j] !=
748:           compiler->vars[insn->src_args[j]].size &&
749:           compiler->vars[insn->src_args[j]].vartype != ORC_VAR_TYPE_PARAM &&
750:           compiler->vars[insn->src_args[j]].vartype != ORC_VAR_TYPE_CONST) {
751:         ORC_COMPILER_ERROR(compiler, "size mismatch, opcode %s src[%d] is %d should be %d",
752:             opcode->name, j, compiler->vars[insn->src_args[j]].size,
753:             multiplier * opcode->src_size[j]);
754:         compiler->result = ORC_COMPILE_RESULT_UNKNOWN_PARSE;
755:         return;
756:       }
757:       if (opcode->flags & ORC_STATIC_OPCODE_SCALAR && j >= 1 &&
758:           compiler->vars[insn->src_args[j]].vartype != ORC_VAR_TYPE_PARAM &&
759:           compiler->vars[insn->src_args[j]].vartype != ORC_VAR_TYPE_CONST) {
760:         ORC_COMPILER_ERROR(compiler, "opcode %s requires const or param source",
761:             opcode->name);
762:         compiler->result = ORC_COMPILE_RESULT_UNKNOWN_PARSE;
763:         return;
764:       }
765:       max_size = MAX(max_size, multiplier * opcode->src_size[j]);
766:     }
767:     if (opcode->flags & ORC_STATIC_OPCODE_SCALAR &&
768:         opcode->src_size[1] == 0 &&
769:         compiler->vars[insn->src_args[0]].vartype != ORC_VAR_TYPE_PARAM &&
770:         compiler->vars[insn->src_args[0]].vartype != ORC_VAR_TYPE_CONST) {
771:       ORC_COMPILER_ERROR(compiler, "opcode %s requires const or param source",
772:           opcode->name);
773:       compiler->result = ORC_COMPILE_RESULT_UNKNOWN_PARSE;
774:       return;
775:     }
776:   }
777:   compiler->max_var_size = max_size;
778: }
