780: /**
781:  * orc_compiler_get_max_loop_shift:
782:  * @compiler: The OrcCompiler instance
783:  * @shift: Output parameter for the calculated shift value
784:  *
785:  * Calculate the maximum loop shift based on how many elements of the
786:  * maximum variable size can fit in a SIMD register.
787:  *
788:  * This calculates loop_shift = log2(register_size / max_var_size), which
789:  * determines how many elements can be processed per iteration:
790:  * elements_per_iteration = 2^loop_shift = register_size / max_var_size
791:  *
792:  * Returns: #TRUE if the operation succeeds, #FALSE otherwise
793:  */
794: orc_bool
795: orc_compiler_get_max_loop_shift (OrcCompiler *compiler, int *shift)
796: {
797:   int n = 2;
798:   int i;
799:   const int register_size = compiler->target->register_size;
800:   const int var_size = compiler->max_var_size;
801:   const int max_elements = register_size / var_size;
802: 
803:   if (var_size <= 0 || register_size <= 0) {
804:     ORC_ERROR ("Invalid sizes: var_size=%d, register_size=%d", var_size, register_size);
805:     return FALSE;
806:   }
807: 
808:   if (max_elements <= 1) {
809:     *shift = 0;
810:     return TRUE;
811:   }
812: 
813:   for (i = 1; i < 32; i++) {  /* Safety limit: 2^32 = 4GB elements */
814:     if (max_elements == n) {
815:       *shift = i;
816:       return TRUE;
817:     }
818:     n *= 2;
819:   }
820: 
821:   ORC_ERROR ("Invalid configuration: register_size=%d not cleanly divisible by var_size=%d",
822:             register_size, var_size);
823:   return FALSE;
824: }
