880: static void
881: orc_compiler_rewrite_insns (OrcCompiler *compiler)
882: {
883:   int i;
884:   int j;
885:   OrcStaticOpcode *opcode;
886:   OrcProgram *program = compiler->program;
887: 
888:   compiler->n_insns = 0;
889:   for(j=0;j<program->n_insns;j++){
890:     OrcInstruction insn;
891:     OrcInstruction *xinsn;
892: 
893:     memcpy (&insn, program->insns + j, sizeof(OrcInstruction));
894:     opcode = insn.opcode;
895: 
896:     if (!(opcode->flags & ORC_STATIC_OPCODE_LOAD)) {
897:       for(i=0;i<ORC_STATIC_OPCODE_N_SRC;i++){
898:         OrcVariable *var;
899: 
900:         if (opcode->src_size[i] == 0) continue;
901:         var = compiler->vars + insn.src_args[i];
902: 
903:         if (i > 0 && (opcode->flags & ORC_STATIC_OPCODE_SCALAR) &&
904:             (!compiler->load_params || var->vartype != ORC_VAR_TYPE_PARAM))
905:           continue;
906: 
907:         if (var->vartype == ORC_VAR_TYPE_SRC ||
908:             var->vartype == ORC_VAR_TYPE_DEST) {
909:           OrcInstruction *cinsn;
910: 
911:           cinsn = compiler->insns + compiler->n_insns;
912:           compiler->n_insns++;
913: 
914:           cinsn->flags = insn.flags;
915:           cinsn->flags |= ORC_INSN_FLAG_ADDED;
916:           cinsn->flags &= ~(ORC_INSTRUCTION_FLAG_X2|ORC_INSTRUCTION_FLAG_X4);
917:           cinsn->opcode = get_load_opcode_for_size (var->size);
918:           cinsn->dest_args[0] = orc_compiler_new_temporary (compiler,
919:               var->size);
920:           cinsn->src_args[0] = insn.src_args[i];
921:           insn.src_args[i] = cinsn->dest_args[0];
922:         } else if (var->vartype == ORC_VAR_TYPE_CONST ||
923:             var->vartype == ORC_VAR_TYPE_PARAM) {
924:           OrcInstruction *cinsn;
925:           int l, multiplier, loaded;
926: 
927:           multiplier = 1;
928:           if (insn.flags & ORC_INSTRUCTION_FLAG_X2) {
929:             multiplier = 2;
930:           }
931:           if (insn.flags & ORC_INSTRUCTION_FLAG_X4) {
932:             multiplier = 4;
933:           }
934: 
935:           loaded = -1;
936:           for(l=0;l<ORC_N_COMPILER_VARIABLES;l++){
937:             if (compiler->vars[l].name == NULL) continue;
938:             if (!compiler->vars[l].has_parameter) continue;
939:             if (compiler->vars[l].parameter != insn.src_args[i]) continue;
940:             if (compiler->vars[l].size != opcode->src_size[i] * multiplier) continue;
941:             loaded = l;
942:             break;
943:           }
944:           if (loaded != -1) {
945:             insn.src_args[i] = loaded;
946:             continue;
947:           }
948:           cinsn = compiler->insns + compiler->n_insns;
949:           compiler->n_insns++;
950: 
951:           cinsn->flags = insn.flags;
952:           cinsn->flags |= ORC_INSN_FLAG_ADDED;
953:           cinsn->opcode = get_loadp_opcode_for_size (opcode->src_size[i]);
954:           cinsn->dest_args[0] = orc_compiler_new_temporary (compiler,
955:               opcode->src_size[i] * multiplier);
956:           if (var->vartype == ORC_VAR_TYPE_CONST) {
957:             compiler->vars[cinsn->dest_args[0]].flags |=
958:                 ORC_VAR_FLAG_VOLATILE_WORKAROUND;
959:           }
960:           compiler->vars[cinsn->dest_args[0]].has_parameter = TRUE;
961:           compiler->vars[cinsn->dest_args[0]].parameter = insn.src_args[i];
962:           cinsn->src_args[0] = insn.src_args[i];
963:           insn.src_args[i] = cinsn->dest_args[0];
964:         }
965:       }
966:     }
967: 
968:     xinsn = compiler->insns + compiler->n_insns;
969:     memcpy (xinsn, &insn, sizeof(OrcInstruction));
970:     compiler->n_insns++;
971: 
972:     if (!(opcode->flags & ORC_STATIC_OPCODE_STORE)) {
973:       for(i=0;i<ORC_STATIC_OPCODE_N_DEST;i++){
974:         OrcVariable *var;
975: 
976:         if (opcode->dest_size[i] == 0) continue;
977: 
978:         var = compiler->vars + insn.dest_args[i];
979:         if (var->vartype == ORC_VAR_TYPE_DEST) {
980:           OrcInstruction *cinsn;
981: 
982:           cinsn = compiler->insns + compiler->n_insns;
983:           compiler->n_insns++;
984: 
985:           cinsn->flags = xinsn->flags;
986:           cinsn->flags |= ORC_INSN_FLAG_ADDED;
987:           cinsn->flags &= ~(ORC_INSTRUCTION_FLAG_X2|ORC_INSTRUCTION_FLAG_X4);
988:           cinsn->opcode = get_store_opcode_for_size (var->size);
989:           cinsn->src_args[0] = orc_compiler_new_temporary (compiler, var->size);
990:           cinsn->dest_args[0] = xinsn->dest_args[i];
991:           xinsn->dest_args[i] = cinsn->src_args[0];
992:         }
993:       }
994:     }
995: 
996:   }
997: }
