1019: int
1020: orc_compiler_get_temp_reg (OrcCompiler *compiler)
1021: {
1022:   int j;
1023: 
1024:   ORC_DEBUG("at insn %d %s", compiler->insn_index,
1025:       compiler->insns[compiler->insn_index].opcode->name);
1026: 
1027:   /* Mark old temp registers as unused */
1028:   for(j=0;j<ORC_N_REGS;j++){
1029:     compiler->alloc_regs[j] = compiler->temp_regs[j];
1030:   }
1031: 
1032:   /* Mark variables using a temp register as used */
1033:   for(j=0;j<ORC_N_COMPILER_VARIABLES;j++){
1034:     if (!compiler->vars[j].alloc) continue;
1035: 
1036:     ORC_DEBUG("var %d: %d  %d %d", j, compiler->vars[j].alloc,
1037:         compiler->vars[j].first_use,
1038:         compiler->vars[j].last_use);
1039: 
1040:     if (compiler->vars[j].first_use == -1) {
1041:       compiler->alloc_regs[compiler->vars[j].alloc] = 1;
1042:     } else if (compiler->vars[j].first_use <= compiler->insn_index &&
1043:         compiler->vars[j].last_use >= compiler->insn_index) {
1044:       compiler->alloc_regs[compiler->vars[j].alloc] = 1;
1045:     }
1046:   }
1047: 
1048:   /* Mark constants using a temp register as used */
1049:   for(j=0;j<compiler->n_constants;j++){
1050:     if (compiler->constants[j].alloc_reg) {
1051:       compiler->alloc_regs[compiler->constants[j].alloc_reg] = 1;
1052:     }
1053:   }
1054: 
1055:   for (j = compiler->min_temp_reg; j < ORC_N_REGS; j++) {
1056:     if (compiler->valid_regs[j] && !compiler->alloc_regs[j]) {
1057:       ORC_DEBUG("Available register %d found", j);
1058:       compiler->temp_regs[j] = 1;
1059:       return j;
1060:     }
1061:   }
1062: 
1063:   ORC_ERROR("No temporary register available at insn %d %s",
1064:       compiler->insn_index,
1065:       compiler->insns[compiler->insn_index].opcode->name);
1066:   ORC_COMPILER_ERROR (compiler, "no temporary register available");
1067:   compiler->result = ORC_COMPILE_RESULT_UNKNOWN_COMPILE;
1068: 
1069:   return 0;
1070: }
