1089: static void
1090: orc_compiler_rewrite_vars (OrcCompiler *compiler)
1091: {
1092:   int j;
1093:   int k;
1094:   OrcInstruction *insn;
1095:   OrcStaticOpcode *opcode;
1096:   int var;
1097:   int actual_var;
1098: 
1099:   for(j=0;j<ORC_N_COMPILER_VARIABLES;j++){
1100:     if (compiler->vars[j].alloc) continue;
1101:     compiler->vars[j].last_use = -1;
1102:   }
