294: 
295:   ex->accumulators[0] = 0;
296:   ex->accumulators[1] = 0;
297:   ex->accumulators[2] = 0;
298:   ex->accumulators[3] = 0;
299: 
300:   ORC_DEBUG("emulating");
301: 
302:   memset (&opcode_ex, 0, sizeof(opcode_ex));
303: 
304:   if (code == NULL) {
305:     ORC_ERROR("attempt to run program that failed to compile");
