307:   }
308: 
309:   if (code->is_2d) {
310:     m = ORC_EXECUTOR_M(ex);
311:   } else {
312:     m = 1;
313:   }
314: 
315:   for(i=0;i<ORC_N_COMPILER_VARIABLES;i++){
316:     OrcCodeVariable *var = code->vars + i;
317: 
318:     if (var->size) {
319:       tmpspace[i] = orc_malloc(ORC_MAX_VAR_SIZE * CHUNK_SIZE);
320:     }
321:   }
322: 
323:   opcode_ex = orc_malloc(sizeof(OrcOpcodeExecutor)*code->n_insns);
324: 
325:   for(j=0;j<code->n_insns;j++){
326:     insn = code->insns + j;
327:     opcode = insn->opcode;
328: 
329:     opcode_ex[j].emulateN = opcode->emulateN;
330:     opcode_ex[j].shift = 0;
331:     if (insn->flags & ORC_INSTRUCTION_FLAG_X2) {
332:       opcode_ex[j].shift = 1;
333:     } else if (insn->flags & ORC_INSTRUCTION_FLAG_X4) {
334:       opcode_ex[j].shift = 2;
335:     }
336: 
337:     for(k=0;k<ORC_STATIC_OPCODE_N_SRC;k++) {
338:       OrcCodeVariable *var = code->vars + insn->src_args[k];
339:       if (opcode->src_size[k] == 0) continue;
340: 
341:       if (var->vartype == ORC_VAR_TYPE_CONST) {
342:         opcode_ex[j].src_ptrs[k] = tmpspace[insn->src_args[k]];
343:         /* FIXME hack */
344:         load_constant (tmpspace[insn->src_args[k]], 8,
345:             var->value.i);
346:       } else if (var->vartype == ORC_VAR_TYPE_PARAM) {
347:         opcode_ex[j].src_ptrs[k] = tmpspace[insn->src_args[k]];
348:         /* FIXME hack */
349:         if (var->size == 8) {
350:           load_constant (tmpspace[insn->src_args[k]], 8,
351:               (orc_uint64)(orc_uint32)ex->params[insn->src_args[k]] |
352:               (((orc_uint64)(orc_uint32)ex->params[insn->src_args[k] +
353:                (ORC_N_PARAMS)])<<32));
354:         } else {
355:           load_constant (tmpspace[insn->src_args[k]], 8,
356:               ex->params[insn->src_args[k]]);
357:         }
358:       } else if (var->vartype == ORC_VAR_TYPE_TEMP) {
359:         opcode_ex[j].src_ptrs[k] = tmpspace[insn->src_args[k]];
360:       } else if (var->vartype == ORC_VAR_TYPE_SRC) {
361:         if (ORC_PTR_TO_INT(ex->arrays[insn->src_args[k]]) & (var->size - 1)) {
362:           ORC_ERROR("Unaligned array for src%d, program %s",
363:               (insn->src_args[k]-ORC_VAR_S1), name);
364:         }
365:         opcode_ex[j].src_ptrs[k] = ex->arrays[insn->src_args[k]];
366:       } else if (var->vartype == ORC_VAR_TYPE_DEST) {
367:         if (ORC_PTR_TO_INT(ex->arrays[insn->src_args[k]]) & (var->size - 1)) {
368:           ORC_ERROR("Unaligned array for dest%d, program %s",
369:               (insn->src_args[k]-ORC_VAR_D1), name);
370:         }
371:         opcode_ex[j].src_ptrs[k] = ex->arrays[insn->src_args[k]];
372:       }
373:     }
374:     for(k=0;k<ORC_STATIC_OPCODE_N_DEST;k++) {
375:       OrcCodeVariable *var = code->vars + insn->dest_args[k];
376:       if (opcode->dest_size[k] == 0) continue;
377: 
378:       if (var->vartype == ORC_VAR_TYPE_TEMP) {
379:         ORC_DEBUG("dest vartype tmp %d", insn->dest_args[k]);
380:         opcode_ex[j].dest_ptrs[k] = tmpspace[insn->dest_args[k]];
381:       } else if (var->vartype == ORC_VAR_TYPE_ACCUMULATOR) {
382:         opcode_ex[j].dest_ptrs[k] =
383:           &ex->accumulators[insn->dest_args[k] - ORC_VAR_A1];
384:       } else if (var->vartype == ORC_VAR_TYPE_DEST) {
385:         if (ORC_PTR_TO_INT(ex->arrays[insn->dest_args[k]]) & (var->size - 1)) {
386:           ORC_ERROR("Unaligned array for dest%d, program %s",
