388:         }
389:         opcode_ex[j].dest_ptrs[k] = ex->arrays[insn->dest_args[k]];
390:       }
391:     }
392:     ORC_DEBUG("opcode %s %p %p %p", opcode->name,
393:         opcode_ex[j].dest_ptrs[0], opcode_ex[j].src_ptrs[0],
394:         opcode_ex[j].src_ptrs[1]);
395:   }
