397:   ORC_DEBUG("src ptr %p stride %d", ex->arrays[ORC_VAR_S1], ex->params[ORC_VAR_S1]);
398:   for(m_index=0;m_index<m;m_index++){
399:     ORC_DEBUG("m_index %d m %d", m_index, m);
400: 
401:     for(j=0;j<code->n_insns;j++){
402:       insn = code->insns + j;
403:       opcode = insn->opcode;
404: 
